body:not(.BasketIndexRoute) #header{
position: fixed;
}

.espelho-home #middle{
  max-width: 100%!important;
  width:100%;
}

.carrinho-vazio {
	display: none !important;
}

.espelho-home  .wrapper:before, 
.espelho-home  .wrapper:after{
  content: unset!important;
}

.espelho-home .wd-browsing-breadcrumbs, .accordionpdpnew.mobile, body.page-basket #middle .custom-embalagem {
   display: none;
}

.level-1 .colecoes .lola-accordion li:has(a[href*="/ondulado"]), .colecoes .lola-accordion li:has(a[href*="/crespo"]){
    display: block !important;
}

.level-1 .tipos-de-cabelo .lola-accordion li:has(a[href*="/ondulado"]),
.level-1 .tipos-de-cabelo .lola-accordion li:has(a[href*="/tipos-de-cabelo/crespo"])  {
	display: none;
}



.espelho-home .wd-marketing-banner img{
  width: 100%;
  height: auto;
}

.accordionpdpnew details {
  display: block;
  width: 100%;
  margin: 10px 0;
}

.accordionpdpnew .accordion-content {
  padding: 16px 0 0 0px;
  font-size: 12px;
  color: #A2A2A2;
  font-family: 'Lato';
}

#main .accordionpdpnew summary, body[class*="context-product-"] #main #middle .product-detail .ingrediente-descricao .wd-content .wd-descriptions-text h1 {
  display: flex;
    background: transparent;
    color: #3f3f3f;
    border-radius: 0;
    padding: 8px 0px;
	padding-bottom: 16px;
    cursor: pointer;
    font-weight: 500;
    justify-content: flex-start;
    align-items: center;
    list-style: none;
    font-family: 'obviously';
    font-size: 14px;
    border-bottom: 1px solid #ECECEC;
	position: relative;
}

.accordionpdpnew summary::-webkit-details-marker {
  display: none;
}

#main .accordionpdpnew summary:before, body[class*="context-product-"] #main #middle .product-detail .ingrediente-descricao .wd-content .wd-descriptions-text h1:after {
  content: "";
  font-weight: bold;
  margin: 0 5px 0 0;
  width: 16px;
  height: 16px; 
  text-align: center;
  background: url('/sites/www-lolacosmetics-com-br-b005530a/root-8a5edab2/arrow-up-gray.svg-54f20aa0.svg') no-repeat;
  background-position: center;
  position: absolute;
  right: 0;
}

#main .accordionpdpnew details[open] summary:before, body[class*="context-product-"] #main #middle .product-detail .ingrediente-descricao .wd-content .wd-descriptions-text h1.active-ativos:after {
  content: "";
  background: url('/sites/www-lolacosmetics-com-br-b005530a/root-8a5edab2/arrow-down-gray.svg-45cc2f1d.svg') no-repeat;
  background-position: center;
}
body[class*="context-product-"] #main #middle .product-detail .ingrediente-descricao .wd-content .wd-descriptions-text h2 {
    color: #A2A2A2;
    font-size: 14px;
    font-family: "Lato", sans-serif;
}

.BasketIndexRoute #popup-overlay {
	display: none !important;
}
#header .main-bar{
	background: #FFF !important;
}
#header .main-bar .wrapper .row #logo a {
    background: url('/sites/www-lolacosmetics-com-br-b005530a/root-8a5edab2/logo-lola-15anos.svg-944cf132.svg') !important;
	width: 120px !important;
	height: 120px !important;
}

/* Novo Menu Lola*/
.novo-menu .wd-category-menu .level-1 {
    display: flex;
    justify-content: space-between;
}

.novo-menu .wd-category-menu .level-1>li {
    height: 56px;
    position: relative;
}

.novo-menu .wd-category-menu .level-1>li .icon {
    display: none;
}

.novo-menu .wd-category-menu .level-1>li h3 {
    margin: 0;
}

.novo-menu .wd-category-menu .level-1>li h3 a {
	color: #3F3F3F;
    display: block;
    line-height: 56px;
    text-align: center;
    height: 56px;
    text-transform: uppercase;
    font-family: "Lato";
    font-weight: 800;
    cursor: pointer;
    font-size: 15px;
    text-decoration: none;
}

#main .novo-menu .wd-category-menu .level-1 .sub-section.level-2 {
 position: absolute;
    top: 100%;
    left: -6px;
    /* transform: translateX(-50%); */

	display: grid;
   	grid-template-columns: repeat(2, 1fr) !important;
	grid-template-rows: repeat(5, max-content) !important;

    padding: 0 20px 0;

    background-color: #FFF;
    box-shadow: 0 8px 12px -6px rgba(0,0,0,0.2);

    gap: 8px 24px;

    width: max-content;
	max-height: 0;

	overflow: hidden;
 	transition: max-height 0.35s ease, padding 0.3s ease;

	max-width: 1240px !important;
	border-radius:0 0 10px 10px;
	align-items: flex-start;
}

#main .novo-menu .wd-category-menu .level-1 .colecoes .sub-section.level-2{
    transform: translateX(-50%);
}

.novo-menu .wd-category-menu .level-1 .tipos-de-cabelo .level-2, .novo-menu .wd-category-menu .level-1 .promocao .level-2 {
grid-template-columns: repeat(1, 1fr) !important;
}
.novo-menu .wd-category-menu .level-1 .tipos-de-cabelo .level-2{
min-width: 100px;
}

.novo-menu .wd-category-menu .level-1 > li:hover .level-2 {
display: grid;
max-height: 600px !important;
padding: 10px 20px 5px !important;

}

.novo-menu .wd-category-menu .level-1 > li:last-child .level-2 {
    left: auto;
    right: -6px;
}


.novo-menu .wd-category-menu .level-1 .level-2 .level-3 {
	position: absolute;
	left: 250px;
	width: 0;
	height: 300px;
	top: 0;
	padding-top: 30px;
	padding-bottom: 30px;
	filter: drop-shadow(0px 3px 6px rgba(0, 0, 0, 0.16));
	overflow: hidden;
	transition: all 0.3s ease;

}
.novo-menu .wd-category-menu .level-1 .level-2 > li {
	margin-bottom: 5px;
	max-width: 190px;
}
.novo-menu .wd-category-menu .level-1 .level-2 > li.has-children > h4 > a {
	display: flex;
	align-items: center;
	justify-content: space-between;
	padding-right: 0;
}
.novo-menu .wd-category-menu .level-1 .level-2 > li.has-children > h4 > a .icon {
	display: block;
}
.novo-menu .wd-category-menu .level-1 .level-2 > li.has-children:hover > h4 > a .icon svg path {
	fill: #3F3F3F;
}
.novo-menu .wd-category-menu .level-1 .level-2 > li:hover .level-3 {
	width: 300px;
}
.novo-menu .wd-category-menu .level-1 .level-2 > li a {
	color: #3F3F3F;
	font-family: "Lato";
	font-weight: 500;
	font-size: 16px !important;
	text-decoration: none;
	padding: 0;
	display: block;

	letter-spacing: 0.03em;
	transition: color .3s ease;
}

.novo-menu .wd-category-menu .level-1 .level-2 > li  a:hover {
    color: #EA136A;
}
.novo-menu .wd-category-menu .level-1 .level-2 > li h4 {
	margin: 0;
}

.novo-menu .wd-category-menu .category-banner{ 
